p=argparse.ArgumentParser()
p.add_argument('--mode',choices=['validate-publish','publish','validate-activate','activate'],required=True)
args=p.parse_args()
root=pathlib.Path('.')
conf=root/'cosmos-legal-config.json'
if not conf.exists():raise SystemExit('ERROR: legal configuration missing; no files changed.')
try: cfg=json.loads(conf.read_text())
except Exception as e:raise SystemExit('ERROR: invalid JSON configuration: '+str(e))
for key in ['operator_name','legal_email','dmca_email','mailing_address']:
 value=cfg.get(key,'')
 if not isinstance(value,str) or len(value.strip())<6 or len(value)>240 or any(mark in value.upper() for mark in ['YOUR_','REPLACE','PLACEHOLDER','EXAMPLE','TBD']):
  raise SystemExit('ERROR: real '+key+' is required before legal publication. No changes made.')
if not all(re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+',cfg[k]) for k in ['legal_email','dmca_email']):
 raise SystemExit('ERROR: both legal email addresses must be valid. No changes made.')
if cfg.get('approved_for_publication') is not True:
 raise SystemExit('ERROR: do not publish until the operator has checked all facts, contact details, and the final documents, and sets approved_for_publication=true.')
clean={}
for name,blob in PAGES.items():
 data=zlib.decompress(base64.b85decode(blob)).decode()
 for label,key in [('{{OPERATOR_NAME}}','operator_name'),('{{LEGAL_EMAIL}}','legal_email'),('{{DMCA_EMAIL}}','dmca_email'),('{{LEGAL_ADDRESS}}','mailing_address')]:
  data=data.replace(label,html.escape(cfg[key],quote=True))
 if '{{' in data:raise SystemExit('ERROR: unfilled template placeholder in '+name)
 data=data.replace('<!doctype html>','<!doctype html><!-- COSMOS_LEGAL_VERSION: '+VERSION+' -->',1)
 clean[name]=data
if args.mode.endswith('publish'):
 for name,data in clean.items():
  file=root/name
  if file.exists() and file.read_text()!=data and 'COSMOS_LEGAL_VERSION: '+VERSION not in file.read_text(errors='replace'):
   raise SystemExit('ERROR: will not overwrite another legal page: '+name)
 if args.mode=='validate-publish':
  print('PASS: legal operator config and all 3 policy documents ready; no files changed.');sys.exit(0)
 for name,data in clean.items():(root/name).write_text(data,encoding='utf-8')
 print('PUBLISHED TO REPOSITORY: three legal pages. Wait for GitHub Pages deployment and verify 200 OK before activation.');sys.exit(0)
source=root/'cosmos-next.html'
if not source.exists():raise SystemExit('ERROR: frontend missing')
original=source.read_bytes()
sha=lambda b:hashlib.sha256(b).hexdigest()
if sha(original)==LEGAL_SHA:
 print('PASS: legal acceptance frontend already installed.');sys.exit(0)
if sha(original)!=CORE_SHA:
 raise SystemExit('ERROR: expected exact v9.5.3 Metro-only frontend. No changes made.')
# Check public pages, not just local files. Case-sensitive URLs; fail CLOSED.
for name in clean:
 url='https://ptdtoday.com/'+name
 try:
  with urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'COSMOS-legal-preflight/1'}),timeout=15) as r:
   page=r.read(45000).decode('utf-8','replace')
   if r.status!=200 or 'COSMOS_LEGAL_VERSION: '+VERSION not in page or '<html' not in page.lower():
    raise ValueError('wrong policy version or invalid HTML')
 except Exception as e:raise SystemExit('ERROR: public policy not ready at '+url+' ('+str(e)+'). No changes made.')
try:
 with urllib.request.urlopen('https://ptdtoday-cosmos-life.ptdtoday.workers.dev/api/health',timeout=15) as r:
  health=json.load(r)
  if health.get('version')!='cosmos-life-v9.5.3-staged-legal-acceptance':raise ValueError('expected v9.5.3 staged legal-aware Life Worker')
except Exception as e:raise SystemExit('ERROR: legal-aware Life Worker not confirmed: '+str(e)+'. No changes made.')
with tempfile.TemporaryDirectory() as td:
 diff=zlib.decompress(base64.b85decode(PATCH)).decode()
 path=pathlib.Path(td)/'legal.diff';path.write_text(diff)
 check=subprocess.run(['git','apply','--check',str(path)],capture_output=True,text=True)
 if check.returncode:raise SystemExit('ERROR: guarded legal frontend patch mismatch: '+check.stderr)
 if args.mode=='validate-activate':
  print('PASS: all 3 policy links HTTP 200, Worker health version and guarded legal patch validated. No changes made.');sys.exit(0)
 result=subprocess.run(['git','apply',str(path)],capture_output=True,text=True)
 if result.returncode:raise SystemExit('ERROR: legal patch could not be applied: '+result.stderr)
 if sha(source.read_bytes())!=LEGAL_SHA:
  source.write_bytes(original)
  raise SystemExit('ERROR: output checksum differed; original frontend restored.')
 print('ACTIVATED: server-recorded Terms for new and existing members (requires completed D1 legal migration).')
